const $=s=>document.querySelector(s), fmt=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n||0)), num=n=>new Intl.NumberFormat('id-ID').format(Number(n||0)), date=v=>new Date(v).toLocaleString('id-ID');
let token=localStorage.getItem('acis_token')||'', me=null, master=null, cart=[];
let promoDiscount=0,promoApplied='',splitPayments=[],loyaltySettings={enabled:true,rupiahPerPoint:10000,pointValue:1000,minRedeemPoints:1};
let navItems=[['dashboard','⌂','Dashboard'],['hub-sales','◈','Penjualan'],['pos','▦','Kasir (POS)'],['products','□','Produk'],['inventory','↕','Stok Ledger'],['purchases','⇩','Pembelian'],['sales','⇧','Riwayat Penjualan'],['shifts','◴','Shift Kasir'],['partners','◎','Pelanggan & Supplier'],['promotions','✦','Promo & Loyalty'],['returns','↩','Retur & Void'],['finance','₿','Hutang & Piutang'],['reports','▥','Laporan'],['expenses','¤','Biaya Operasional'],['devices','⌁','Printer & Barcode'],['users','♙','User & Role'],['subscription','◇','Langganan'],['settings','⚙','Pengaturan'],['integration','↗','Integrasi Accurate'],['audit','◷','Audit Log']];
function toast(msg,bad=false){const t=$('#toast');t.textContent=msg;t.style.cssText=`position:fixed;right:24px;top:20px;z-index:99;padding:12px 16px;border-radius:12px;color:white;background:${bad?'#d84b5d':'#24334f'};box-shadow:0 12px 40px #0003`;clearTimeout(window._tt);window._tt=setTimeout(()=>t.removeAttribute('style'),2600)}
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})};const r=await fetch(url,opt);let d={};try{d=await r.json()}catch{}if(!r.ok){if(r.status===401)logout();throw new Error(d.error||'Terjadi kesalahan.')}return d}
function rupInput(v=0){return `<input type="number" min="0" step="1" value="${Number(v||0)}">`}
function safeHtml(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function productVisual(p,cls='picon'){return p?.imageData?`<img class="product-photo ${cls}" src="${p.imageData}" alt="${safeHtml(p.name)}">`:`<div class="${cls}">${safeHtml((p?.name||'?')[0]?.toUpperCase()||'?')}</div>`}
function readProductImage(input,preview){const f=input.files?.[0];if(!f)return;if(f.size>1200000){input.value='';return toast('Ukuran foto maksimal 1.2 MB',true)}const r=new FileReader();r.onload=()=>{input.dataset.value=r.result;preview.innerHTML=`<img src="${r.result}" class="upload-preview-img">`};r.readAsDataURL(f)}
function openModal(title,body,onSave){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card"><div class="modal-head"><h3>${title}</h3><button class="close">×</button></div>${body}<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:18px"><button class="secondary cancel">Batal</button><button class="primary save">Simpan</button></div></div>`;document.body.appendChild(m);m.querySelector('.close').onclick=m.querySelector('.cancel').onclick=()=>m.remove();m.querySelector('.save').onclick=async()=>{try{await onSave(m);m.remove()}catch(e){toast(e.message,true)}};return m}
function renderNav(){const n=$('#nav');n.innerHTML=navItems.map(([id,ico,name])=>`<div class="nav-group"><button class="nav-item" data-view="${id}"><span class="ico">${ico}</span><span>${name}</span></button></div>`).join('');n.onclick=e=>{const b=e.target.closest('[data-view]');if(b)go(b.dataset.view)}}
function setActive(v){document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===v));const i=navItems.find(x=>x[0]===v);$('#crumb').textContent=i?.[2]||'ACIS POS';$('.sidebar').classList.remove('open')}
async function go(view){location.hash=view;setActive(view);const routes={dashboard:renderDashboard,'hub-sales':renderHub,pos:renderPOS,products:renderProducts,inventory:renderInventory,purchases:renderPurchases,sales:renderSales,partners:renderPartners,promotions:renderPromotions,returns:renderReturns,finance:renderFinance,reports:renderReports,expenses:renderExpenses,devices:renderDevices,users:renderUsers,subscription:renderSubscription,shifts:renderShifts,settings:renderSettings,integration:renderIntegration,audit:renderAudit};try{await (routes[view]||renderDashboard)()}catch(e){console.error('ACIS POS render error:',e);const c=$('#content');if(c)c.innerHTML=`<div class="card error-state"><h2>Halaman gagal dimuat</h2><p>${safeHtml(e.message||'Terjadi kesalahan saat memuat halaman.')}</p><button class="primary" onclick="go('${view}')">Coba Lagi</button></div>`;toast(e.message||'Halaman gagal dimuat',true)}}
async function initApp(){try{me=(await api('/api/me')).user;master=await api('/api/master');$('#loginView').classList.add('hidden');$('#app').classList.remove('hidden');$('#userName').textContent=me.name;$('#userRole').textContent=me.role;$('#userInitial').textContent=me.name[0].toUpperCase();$('#planBadge').textContent=me.subscription?.status==='trial'?'TRIAL 7 HARI':(me.subscription?.plan_name||me.subscription?.planName||'Langganan');const sw=$('#outletSwitcher');sw.innerHTML=(master.outlets||[]).map(x=>`<option value="${x.id}" ${x.id===me.outlet?.id?'selected':''}>${x.name}</option>`).join('');sw.onchange=async()=>{const d=await api('/api/session/outlet',{method:'POST',body:JSON.stringify({outletId:sw.value})});token=d.token;localStorage.setItem('acis_token',token);await initApp()};renderNav();const s=await api('/api/settings');$('#companyMini').textContent=s.companyName||me.tenant?.name||'Workspace';go(location.hash.replace('#','')||'dashboard')}catch(e){logout(false)}}
function logout(reload=true){token='';me=null;localStorage.removeItem('acis_token');if(reload)location.href='/'}
function registerModal(){openModal('Buat Akun ACIS POS — Trial 7 Hari',`<p class="register-intro">Daftarkan bisnis Anda. Akun langsung aktif dengan masa trial 7 hari.</p><div class="form-grid"><label>Nama Bisnis<input id="rgBusiness" placeholder="Contoh: Toko Makmur"></label><label>Nama Pemilik<input id="rgName" placeholder="Nama lengkap"></label><label>Email<input id="rgEmail" type="email" placeholder="nama@email.com"></label><label>Username<input id="rgUsername" autocomplete="username" placeholder="Buat username"></label><label class="full">Password<input id="rgPassword" type="password" autocomplete="new-password" placeholder="Minimal 6 karakter"></label></div><div class="trial-note"><b>Trial 7 hari</b><span>Setelah masa trial berakhir, langganan dapat diaktifkan oleh tim ACIS sesuai paket yang dipilih.</span></div>`,async m=>{const businessName=m.querySelector('#rgBusiness').value.trim(),name=m.querySelector('#rgName').value.trim(),email=m.querySelector('#rgEmail').value.trim(),username=m.querySelector('#rgUsername').value.trim(),password=m.querySelector('#rgPassword').value;if(!businessName||!name||!username||password.length<6)throw new Error('Lengkapi data dan gunakan password minimal 6 karakter.');await api('/api/onboarding/register',{method:'POST',body:JSON.stringify({businessName,name,email,username,password,planCode:'MONTHLY'})});const d=await api('/api/login',{method:'POST',body:JSON.stringify({username,password})});token=d.token;localStorage.setItem('acis_token',token);toast('Akun berhasil dibuat. Trial 7 hari sudah aktif.');await initApp()})}
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/login',{method:'POST',body:JSON.stringify({username:$('#username').value,password:$('#password').value})});token=d.token;localStorage.setItem('acis_token',token);await initApp()}catch(e){toast(e.message,true)}};$('#logoutBtn').onclick=()=>logout();$('#mobileMenu').onclick=()=>$('.sidebar').classList.toggle('open');window.onhashchange=()=>token&&go(location.hash.slice(1)||'dashboard');
function pageHead(title,desc,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function kpi(label,value,icon){return `<div class="kpi"><div class="kpi-top"><span>${label}</span><span>${icon}</span></div><div class="num">${value}</div></div>`}
function renderHub(){setActive('hub-sales');const cards=[['pos','▦','Kasir POS','Transaksi cepat dengan pencarian produk, keranjang dan pembayaran.'],['sales','⇧','Riwayat Penjualan','Telusuri invoice dan transaksi yang sudah selesai.'],['partners','◎','Pelanggan & Supplier','Kelola pelanggan, supplier, kontak dan poin.'],['products','□','Master Produk','Harga jual, harga pokok, barcode, kategori dan stok awal.'],['inventory','↕','Stok Ledger','Jejak pergerakan stok masuk, keluar dan penyesuaian.'],['reports','▥','Laporan','Pantau omzet, HPP, laba kotor, biaya dan laba bersih.']];$('#content').innerHTML=pageHead('Pusat Operasional','Akses modul utama ACIS POS melalui kartu navigasi modern.')+`<div class="hub">${cards.map(c=>`<div class="hub-card" onclick="go('${c[0]}')"><div class="ico-big">${c[1]}</div><h3>${c[2]}</h3><p>${c[3]}</p><button>Buka menu →</button></div>`).join('')}</div>`}
async function renderDashboard(){setActive('dashboard');const d=await api('/api/dashboard');const top=d.topProductsMonth||[],maxQty=Math.max(...top.map(x=>x.qty),1);$('#content').innerHTML=pageHead('Dashboard','Ringkasan bisnis hari ini dan indikator yang perlu perhatian.')+`<div class="kpis">${kpi('Penjualan hari ini',fmt(d.totalToday),'↗')}${kpi('Transaksi hari ini',num(d.transactionsToday),'◉')}${kpi('Omzet bulan ini',fmt(d.totalMonth),'◫')}${kpi('Stok menipis',num(d.lowStock.length),'!')}</div><div class="grid-2"><div class="card"><div class="section-title"><h3>Tren 7 hari</h3><small>Penjualan kotor</small></div><div class="bar-chart">${d.daily.map(x=>`<div class="bar" style="height:${Math.max(5,Math.min(100,(x.total/Math.max(...d.daily.map(y=>y.total),1))*100))}%"><span>${x.date.slice(5)}</span></div>`).join('')}</div></div><div class="card"><div class="section-title"><h3>Stok perlu perhatian</h3><button class="ghost" onclick="go('inventory')">Lihat semua</button></div>${d.lowStock.length?d.lowStock.slice(0,7).map(p=>`<div style="display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid var(--line)"><div><b>${p.name}</b><small style="display:block;color:var(--muted)">${p.sku}</small></div><span class="stock-chip low">${p.stock}</span></div>`).join(''):'<div class="empty">Semua stok aman.</div>'}</div></div><div class="card top-products-card" style="margin-top:18px"><div class="section-title"><div><h3>Barang Terlaris Bulan Ini</h3><small>Berdasarkan jumlah barang terjual pada bulan berjalan</small></div><button class="ghost" onclick="go('reports')">Lihat laporan</button></div><div class="top-product-chart">${top.length?top.map((x,i)=>`<div class="top-product-row"><div class="top-product-label"><span class="rank">${i+1}</span><div><b>${safeHtml(x.name)}</b><small>${num(x.qty)} terjual • ${fmt(x.revenue)}</small></div></div><div class="top-product-track"><i style="width:${Math.max(6,(x.qty/maxQty)*100)}%"></i></div></div>`).join(''):'<div class="empty">Belum ada penjualan pada bulan ini.</div>'}</div></div><div class="card" style="margin-top:18px"><div class="section-title"><h3>Transaksi terbaru</h3><button class="secondary" onclick="go('pos')">Buka Kasir</button></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Waktu</th><th>Kasir</th><th>Pembayaran</th><th class="right">Total</th></tr></thead><tbody>${d.recent.map(s=>`<tr><td><b>${s.invoice}</b></td><td>${date(s.createdAt)}</td><td>${s.cashier}</td><td>${s.paymentMethod}</td><td class="right"><b>${fmt(s.total)}</b></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Belum ada transaksi.</td></tr>'}</tbody></table></div></div>`}

async function renderPOS(){setActive('pos');const [pd,pt,ly]=await Promise.all([api('/api/products'),api('/api/partners?type=customer'),api('/api/loyalty/settings')]);window._posProducts=pd.items.filter(x=>x.active!==false);window._customers=pt.items;loyaltySettings=ly;promoDiscount=0;promoApplied='';splitPayments=[];$('#content').innerHTML=`<div class="pos-layout"><div class="product-panel"><div class="page-head"><div><h1>Kasir</h1><p>Pilih produk, scan barcode, terapkan promo, lalu selesaikan pembayaran.</p></div><div class="pos-actions"><button class="secondary" onclick="startBarcodeScan()">▣ Scan Barcode</button><button class="secondary" onclick="posHold()">Tahan Transaksi</button></div></div><div class="offline-strip" id="offlineStrip"><b>● Online</b><span>Transaksi tersinkron ke server.</span><button class="ghost" onclick="syncPendingSales()">Sinkronkan pending</button></div><div class="toolbar"><input id="posSearch" class="grow" placeholder="Cari nama, SKU, atau barcode..." oninput="filterPOS()" onkeydown="posSearchKey(event)"><select id="posCat" onchange="filterPOS()"><option value="">Semua kategori</option>${master.categories.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></div><div id="posGrid" class="product-grid"></div></div><div class="checkout"><div class="section-title"><h3>Keranjang</h3><span id="cartCount">0 item</span></div><div id="cartList" class="cart-list"></div><div class="total-box"><div class="total-line"><span>Subtotal</span><b id="cartSubtotal">Rp0</b></div><div class="total-line"><span>Diskon manual</span><input id="discount" type="number" min="0" value="0" oninput="renderCart()" style="width:120px;margin:0"></div><div class="promo-row"><input id="promoCode" placeholder="Kode promo / voucher"><button class="secondary" onclick="applyPromo()">Terapkan</button></div><div id="promoInfo" class="mini-note"></div><select id="customer" onchange="customerChanged()"><option value="">Pelanggan Umum</option>${pt.items.map(x=>`<option value="${x.id}">${x.name} • ${num(x.points)} poin</option>`).join('')}</select><div id="loyaltyBox" class="loyalty-box hidden"><span id="customerPoints"></span><label>Redeem poin<input id="redeemPoints" type="number" min="0" value="0" oninput="renderCart()"></label></div><div class="total-line grand"><span>Total</span><span id="cartTotal">Rp0</span></div><select id="payment" onchange="paymentChanged()"><option value="cash">Tunai</option><option value="qris">QRIS</option><option value="transfer">Transfer</option><option value="card">Kartu</option><option value="split">Split Payment</option><option value="credit">Piutang</option></select><div id="normalPay"><input id="paid" type="number" min="0" placeholder="Jumlah bayar"></div><div id="splitInfo" class="split-info hidden"><span>Belum ada pembagian pembayaran.</span><button class="secondary" onclick="configureSplitPayment()">Atur Split</button></div><div id="dueBox" class="hidden"><label>Jatuh tempo<input id="dueDate" type="date"></label></div><button class="primary" onclick="checkout()">Bayar & Selesaikan</button></div></div></div>`;filterPOS();renderCart();updateOnlineState()}
function posSearchKey(e){if(e.key!=='Enter')return;const q=e.target.value.trim().toLowerCase();const p=(window._posProducts||[]).find(x=>String(x.barcode||'').toLowerCase()===q||String(x.sku||'').toLowerCase()===q);if(p){addCart(p.id);e.target.select()}}
function filterPOS(){const q=($('#posSearch')?.value||'').toLowerCase(),c=$('#posCat')?.value||'';const rows=(window._posProducts||[]).filter(p=>(!c||p.categoryId===c)&&(!q||[p.name,p.sku,p.barcode].some(v=>String(v).toLowerCase().includes(q))));$('#posGrid').innerHTML=rows.map(p=>`<div class="product-tile" onclick="addCart('${p.id}')">${productVisual(p,'picon')}<b>${safeHtml(p.name)}</b><small>${safeHtml(p.sku)} • stok ${num(p.stock)}</small><strong>${fmt(p.price)}</strong></div>`).join('')||'<div class="empty">Produk tidak ditemukan.</div>'}
function addCart(id){const p=window._posProducts.find(x=>x.id===id),it=cart.find(x=>x.productId===id);if(it){if(it.qty>=p.stock)return toast('Stok tidak cukup',true);it.qty++}else cart.push({productId:p.id,name:p.name,price:p.price,qty:1,stock:p.stock});renderCart()}
function changeQty(id,d){const it=cart.find(x=>x.productId===id);if(!it)return;it.qty+=d;if(it.qty<=0)cart=cart.filter(x=>x.productId!==id);if(it.qty>it.stock)it.qty=it.stock;renderCart()}
function customerChanged(){const id=$('#customer')?.value,c=(window._customers||[]).find(x=>x.id===id),box=$('#loyaltyBox');if(c&&loyaltySettings.enabled){box.classList.remove('hidden');$('#customerPoints').textContent=`Poin tersedia: ${num(c.points)} • nilai ${fmt(c.points*loyaltySettings.pointValue)}`;$('#redeemPoints').max=c.points}else{box?.classList.add('hidden');if($('#redeemPoints'))$('#redeemPoints').value=0}promoDiscount=0;promoApplied='';if($('#promoInfo'))$('#promoInfo').textContent='';renderCart()}
function paymentChanged(){const p=$('#payment')?.value;$('#normalPay')?.classList.toggle('hidden',p==='split'||p==='credit');$('#splitInfo')?.classList.toggle('hidden',p!=='split');$('#dueBox')?.classList.toggle('hidden',p!=='credit');if(p==='split')configureSplitPayment();renderCart()}
async function applyPromo(){const sub=cart.reduce((a,b)=>a+b.price*b.qty,0),promoCode=$('#promoCode').value.trim();if(!promoCode){promoDiscount=0;promoApplied='';$('#promoInfo').textContent='';return renderCart()}try{const d=await api('/api/promotions/preview',{method:'POST',body:JSON.stringify({promoCode,subtotal:sub,customerId:$('#customer').value||null})});promoDiscount=d.discount;promoApplied=d.code;$('#promoInfo').innerHTML=`<b>${safeHtml(d.name)}</b> • hemat ${fmt(d.discount)}`;renderCart()}catch(e){promoDiscount=0;promoApplied='';toast(e.message,true);renderCart()}}
function renderCart(){const el=$('#cartList');if(!el)return;el.innerHTML=cart.map(x=>`<div class="cart-row"><div><b>${x.name}</b><small>${fmt(x.price)} × ${x.qty}</small></div><div><div class="right"><b>${fmt(x.price*x.qty)}</b></div><div class="qty"><button onclick="changeQty('${x.productId}',-1)">−</button><span>${x.qty}</span><button onclick="changeQty('${x.productId}',1)">+</button></div></div></div>`).join('')||'<div class="empty" style="color:#91a0bc">Keranjang masih kosong.</div>';const sub=cart.reduce((a,b)=>a+b.price*b.qty,0),disc=Number($('#discount')?.value||0),redeem=Math.max(0,Number($('#redeemPoints')?.value||0)),pointDisc=redeem*Number(loyaltySettings.pointValue||0),tot=Math.max(0,sub-disc-promoDiscount-pointDisc);$('#cartSubtotal').textContent=fmt(sub);$('#cartTotal').textContent=fmt(tot);$('#cartCount').textContent=`${cart.reduce((a,b)=>a+b.qty,0)} item`;if($('#paid')&&!$('#paid').value&&$('#payment')?.value!=='credit')$('#paid').value=tot;if($('#payment')?.value==='split'&&splitPayments.length){$('#splitInfo span').textContent=`${splitPayments.map(x=>`${x.method}: ${fmt(x.amount)}`).join(' • ')} | total ${fmt(splitPayments.reduce((a,b)=>a+b.amount,0))}`}}
function configureSplitPayment(){const totalText=$('#cartTotal')?.textContent||'',sub=cart.reduce((a,b)=>a+b.price*b.qty,0),disc=Number($('#discount')?.value||0),redeem=Number($('#redeemPoints')?.value||0),total=Math.max(0,sub-disc-promoDiscount-redeem*Number(loyaltySettings.pointValue||0));openModal('Split Payment',`<p class="hint">Total transaksi: <b>${fmt(total)}</b>. Isi dua atau lebih metode pembayaran.</p><div class="split-grid">${[0,1,2].map((_,i)=>`<div class="split-row"><select id="spMethod${i}"><option value="cash">Tunai</option><option value="qris">QRIS</option><option value="transfer">Transfer</option><option value="card">Kartu</option></select><input id="spAmount${i}" type="number" min="0" value="${splitPayments[i]?.amount||0}" placeholder="Nominal"></div>`).join('')}</div>`,async m=>{splitPayments=[0,1,2].map(i=>({method:m.querySelector(`#spMethod${i}`).value,amount:Number(m.querySelector(`#spAmount${i}`).value||0)})).filter(x=>x.amount>0);if(splitPayments.length<2)throw new Error('Split payment minimal menggunakan 2 metode.');const sum=splitPayments.reduce((a,b)=>a+b.amount,0);if(sum+0.001<total&& !$('#customer').value)throw new Error('Total split payment masih kurang.');renderCart()})}
function makeClientRef(){return `WEB-${Date.now()}-${Math.random().toString(36).slice(2,8)}`}
function pendingSales(){try{return JSON.parse(localStorage.getItem('acis_pending_sales')||'[]')}catch{return []}}
function savePendingSales(x){localStorage.setItem('acis_pending_sales',JSON.stringify(x))}
async function checkout(){if(!cart.length)return toast('Keranjang kosong',true);const method=$('#payment').value,sub=cart.reduce((a,b)=>a+b.price*b.qty,0),disc=Number($('#discount').value||0),redeem=Number($('#redeemPoints')?.value||0);const payload={clientRef:makeClientRef(),items:cart,customerId:$('#customer').value||null,paymentMethod:method,paid:method==='credit'?0:Number($('#paid')?.value||0),payments:method==='split'?splitPayments:undefined,discount:disc,promoCode:promoApplied||$('#promoCode')?.value||'',redeemPoints:redeem,dueDate:$('#dueDate')?.value||null};try{const s=await api('/api/pos/checkout-v2',{method:'POST',body:JSON.stringify(payload)});cart=[];promoDiscount=0;promoApplied='';splitPayments=[];toast(`Transaksi ${s.invoice} berhasil`);printReceipt(s);renderPOS()}catch(e){if(!navigator.onLine||/fetch|network/i.test(String(e.message))){const q=pendingSales();q.push(payload);savePendingSales(q);cart=[];toast('Internet terputus. Transaksi disimpan di perangkat dan akan disinkronkan saat online.');renderPOS()}else toast(e.message,true)}}
async function syncPendingSales(){if(!navigator.onLine)return toast('Masih offline.',true);let q=pendingSales();if(!q.length)return toast('Tidak ada transaksi pending.');let ok=0,remain=[];for(const p of q){try{await api('/api/pos/checkout-v2',{method:'POST',body:JSON.stringify(p)});ok++}catch(e){remain.push(p)}}savePendingSales(remain);toast(`${ok} transaksi offline berhasil disinkronkan${remain.length?`, ${remain.length} masih pending`:''}`,!!remain.length);updateOnlineState()}
function updateOnlineState(){const el=$('#offlineStrip');if(!el)return;const online=navigator.onLine,pending=pendingSales().length;el.classList.toggle('offline',!online);el.querySelector('b').textContent=online?'● Online':'● Offline';el.querySelector('span').textContent=online?(pending?`${pending} transaksi menunggu sinkronisasi.`:'Transaksi tersinkron ke server.'):'Transaksi baru akan disimpan lokal sampai internet kembali.'}
async function posHold(){if(!cart.length)return toast('Keranjang kosong',true);await api('/api/pos/hold',{method:'POST',body:JSON.stringify({items:cart,customerId:$('#customer').value,discount:Number($('#discount').value||0)})});cart=[];toast('Transaksi ditahan');renderPOS()}
function printReceipt(s){const w=window.open('','_blank','width=380,height=650');w.document.write(`<html><head><title>${s.invoice}</title><style>body{font:13px monospace;padding:18px;max-width:320px;margin:auto}h2{text-align:center}.row{display:flex;justify-content:space-between}.dash{border-top:1px dashed #000;margin:8px 0}</style></head><body><h2>ACIS POS</h2><div class="row"><span>${s.invoice}</span><span>${new Date().toLocaleDateString('id-ID')}</span></div><div class="dash"></div>${s.items.map(i=>`<div>${i.name}</div><div class="row"><span>${i.qty} x ${num(i.price)}</span><b>${num(i.subtotal)}</b></div>`).join('')}<div class="dash"></div><div class="row"><b>TOTAL</b><b>${num(s.total)}</b></div><p style="text-align:center">Terima kasih</p><script>print()<\/script></body></html>`);w.document.close()}
async function renderProducts(){setActive('products');const d=await api('/api/products');window._products=d.items;$('#content').innerHTML=pageHead('Manajemen Produk','Kelola SKU, foto, barcode, harga, biaya dan stok minimum.','<button class="primary" onclick="productModal()">+ Tambah Produk</button>')+`<div class="card view-accent"><div class="toolbar"><input id="prodSearch" class="grow" placeholder="Cari produk..." oninput="filterProductTable()"><select id="prodCat" onchange="filterProductTable()"><option value="">Semua kategori</option>${master.categories.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Foto</th><th>SKU</th><th>Produk</th><th>Kategori</th><th class="right">Harga</th><th class="right">Stok</th><th>Status</th><th class="action-cell">Aksi</th></tr></thead><tbody id="productBody"></tbody></table></div></div>`;filterProductTable()}
function filterProductTable(){const q=($('#prodSearch')?.value||'').toLowerCase(),c=$('#prodCat')?.value||'';const rows=(window._products||[]).filter(p=>(!c||p.categoryId===c)&&(!q||[p.sku,p.name,p.barcode].some(v=>String(v||'').toLowerCase().includes(q))));$('#productBody').innerHTML=rows.map(p=>`<tr><td>${productVisual(p,'table-photo')}</td><td><b>${p.sku}</b><small style="display:block;color:var(--muted)">${p.barcode||'-'}</small></td><td>${safeHtml(p.name)}</td><td>${master.categories.find(x=>x.id===p.categoryId)?.name||'-'}</td><td class="right">${fmt(p.price)}</td><td class="right"><b>${num(p.stock)}</b></td><td><span class="stock-chip ${p.stock<=p.minStock?'low':'ok'}">${p.stock<=p.minStock?'Menipis':'Aman'}</span></td><td class="action-cell"><button class="action-btn edit" onclick="productModal('${p.id}')">Edit</button><button class="action-btn delete" onclick="deleteProduct('${p.id}')">Hapus</button></td></tr>`).join('')}
function productModal(id){const p=id?window._products.find(x=>x.id===id):{};openModal(id?'Edit Produk':'Tambah Produk',`<div class="product-upload" id="prodPreview">${p?.imageData?`<img src="${p.imageData}" class="upload-preview-img">`:'<span>Foto produk<br><small>PNG/JPG maks. 1.2 MB</small></span>'}</div><label class="upload-button">Pilih Foto<input id="fImage" type="file" accept="image/png,image/jpeg,image/webp" onchange="readProductImage(this,document.querySelector('#prodPreview'))"></label><div class="form-grid"><label>SKU<input id="fSku" value="${p.sku||''}"></label><label>Barcode<input id="fBarcode" value="${p.barcode||''}"></label><label class="full">Nama Produk<input id="fName" value="${p.name||''}"></label><label>Kategori<select id="fCat">${master.categories.map(x=>`<option value="${x.id}" ${x.id===p.categoryId?'selected':''}>${x.name}</option>`).join('')}</select></label><label>Satuan<select id="fUnit">${master.units.map(x=>`<option value="${x.id}" ${x.id===p.unitId?'selected':''}>${x.name}</option>`).join('')}</select></label><label>Harga Pokok<input id="fCost" type="number" value="${p.cost||0}"></label><label>Harga Jual<input id="fPrice" type="number" value="${p.price||0}"></label><label>Stok<input id="fStock" type="number" value="${p.stock||0}"></label><label>Stok Minimum<input id="fMin" type="number" value="${p.minStock||0}"></label></div>`,async m=>{const fi=m.querySelector('#fImage');const b={sku:m.querySelector('#fSku').value,barcode:m.querySelector('#fBarcode').value,name:m.querySelector('#fName').value,categoryId:m.querySelector('#fCat').value,unitId:m.querySelector('#fUnit').value,cost:Number(m.querySelector('#fCost').value),price:Number(m.querySelector('#fPrice').value),stock:Number(m.querySelector('#fStock').value),minStock:Number(m.querySelector('#fMin').value),imageData:fi.dataset.value||p.imageData||''};await api(id?`/api/products/${id}`:'/api/products',{method:id?'PUT':'POST',body:JSON.stringify(b)});toast('Produk disimpan');renderProducts()})}
async function deleteProduct(id){const p=window._products.find(x=>x.id===id);if(!p||!confirm(`Hapus/nonaktifkan produk ${p.name}?`))return;await api('/api/products/'+id,{method:'DELETE'});toast('Produk dinonaktifkan');renderProducts()}
async function renderInventory(){setActive('inventory');const [p,l]=await Promise.all([api('/api/products'),api('/api/stock-ledger')]);window._products=p.items;$('#content').innerHTML=`<div class="ledger-hero"><h1>Stok Ledger</h1><p>Jejak setiap mutasi stok dari pembelian, penjualan, stok awal, dan penyesuaian manual.</p></div><div class="grid-2"><div class="card"><div class="section-title"><h3>Posisi Stok</h3><button class="primary" onclick="adjustModal()">+ Penyesuaian</button></div><div class="table-wrap"><table><thead><tr><th>Produk</th><th>SKU</th><th class="right">Stok</th><th class="right">Minimum</th></tr></thead><tbody>${p.items.filter(x=>x.active!==false).map(x=>`<tr><td>${x.name}</td><td>${x.sku}</td><td class="right"><b>${x.stock}</b></td><td class="right">${x.minStock}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="section-title"><h3>Mutasi Terbaru</h3><small>${l.items.length} catatan</small></div>${l.items.slice(0,12).map(x=>{const pr=p.items.find(y=>y.id===x.productId);return `<div style="padding:10px 0;border-bottom:1px solid var(--line)"><div style="display:flex;justify-content:space-between"><b>${pr?.name||'Produk'}</b><span>${x.qtyIn?`+${x.qtyIn}`:`-${x.qtyOut}`}</span></div><small style="color:var(--muted)">${x.type} • ${x.reference} • saldo ${x.balance}</small></div>`}).join('')||'<div class="empty">Belum ada mutasi.</div>'}</div></div><div class="card" style="margin-top:18px"><div class="section-title"><h3>Detail Ledger</h3></div><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Produk</th><th>Tipe</th><th>Referensi</th><th class="right">Masuk</th><th class="right">Keluar</th><th class="right">Saldo</th></tr></thead><tbody>${l.items.map(x=>`<tr><td>${date(x.at)}</td><td>${p.items.find(y=>y.id===x.productId)?.name||'-'}</td><td>${x.type}</td><td>${x.reference}</td><td class="right">${x.qtyIn||'-'}</td><td class="right">${x.qtyOut||'-'}</td><td class="right"><b>${x.balance}</b></td></tr>`).join('')}</tbody></table></div></div>`}
function adjustModal(){openModal('Penyesuaian Stok',`<div class="form-grid"><label class="full">Produk<select id="aProd">${window._products.filter(x=>x.active!==false).map(x=>`<option value="${x.id}">${x.name} — stok ${x.stock}</option>`).join('')}</select></label><label>Perubahan Qty<input id="aQty" type="number" placeholder="contoh: 5 atau -3"></label><label>Keterangan<input id="aNote" placeholder="Stock opname / koreksi"></label></div>`,async m=>{await api('/api/stock-adjustments',{method:'POST',body:JSON.stringify({productId:m.querySelector('#aProd').value,quantity:Number(m.querySelector('#aQty').value),note:m.querySelector('#aNote').value})});toast('Stok disesuaikan');renderInventory()})}
async function renderPurchases(){setActive('purchases');const [p,s] = await Promise.all([api('/api/purchases'),api('/api/partners?type=supplier')]);window._purchases=p.items;window._suppliers=s.items;$('#content').innerHTML=pageHead('Pembelian','Catat penerimaan barang dari supplier dan otomatis tambah stok.','<button class="primary" onclick="purchaseModal()">+ Pembelian Baru</button>')+`<div class="card"><div class="table-wrap"><table><thead><tr><th>No. Pembelian</th><th>Waktu</th><th>Supplier</th><th>Item</th><th>Status</th><th class="right">Total</th><th class="action-cell">Aksi</th></tr></thead><tbody>${p.items.map(x=>`<tr><td><b>${x.number}</b></td><td>${date(x.createdAt)}</td><td>${s.items.find(y=>y.id===x.supplierId)?.name||'-'}</td><td>${x.items.length}</td><td><span class="status-chip ok">${x.status||'posted'}</span></td><td class="right"><b>${fmt(x.total)}</b></td><td class="action-cell"><button class="action-btn edit" onclick="editPurchase('${x.id}')">Edit</button><button class="action-btn delete" onclick="deletePurchase('${x.id}')">Hapus</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Belum ada pembelian.</td></tr>'}</tbody></table></div></div>`}
function editPurchase(id){const x=window._purchases.find(v=>v.id===id);if(!x)return;openModal('Edit Pembelian',`<div class="form-grid"><label class="full">Supplier<select id="epSup"><option value="">Tanpa supplier</option>${window._suppliers.map(s=>`<option value="${s.id}" ${s.id===x.supplierId?'selected':''}>${s.name}</option>`).join('')}</select></label><label>Status<select id="epStatus"><option value="posted" ${x.status==='posted'?'selected':''}>Posted</option><option value="draft" ${x.status==='draft'?'selected':''}>Draft</option><option value="received" ${x.status==='received'?'selected':''}>Diterima</option><option value="cancelled" ${x.status==='cancelled'?'selected':''}>Dibatalkan</option></select></label><label class="full">Catatan<textarea id="epNote">${x.note||''}</textarea></label></div><small class="hint">Item dan jumlah stok tidak diubah dari dialog ini agar histori persediaan tetap konsisten.</small>`,async m=>{await api('/api/purchases/'+id,{method:'PUT',body:JSON.stringify({supplierId:m.querySelector('#epSup').value,status:m.querySelector('#epStatus').value,note:m.querySelector('#epNote').value})});toast('Pembelian diperbarui');renderPurchases()})}
async function deletePurchase(id){const x=window._purchases.find(v=>v.id===id);if(!x||!confirm(`Hapus pembelian ${x.number}? Stok dari transaksi ini akan dikembalikan.`))return;try{await api('/api/purchases/'+id,{method:'DELETE'});toast('Pembelian dihapus');renderPurchases()}catch(e){toast(e.message,true)}}
async function purchaseModal(){const [pd,sp]=await Promise.all([api('/api/products'),api('/api/partners?type=supplier')]);openModal('Pembelian Baru',`<div class="form-grid"><label class="full">Supplier<select id="puSup"><option value="">Tanpa supplier</option>${sp.items.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label><label class="full">Produk<select id="puProd">${pd.items.filter(x=>x.active!==false).map(x=>`<option value="${x.id}">${x.name} — ${fmt(x.cost)}</option>`).join('')}</select></label><label>Qty<input id="puQty" type="number" min="1" value="1"></label><label>Harga Pokok<input id="puCost" type="number" min="0" value="0"></label><label>Status Pembayaran<select id="puPayStatus"><option value="paid">Lunas</option><option value="debt">Hutang</option></select></label><label>Jatuh Tempo<input id="puDue" type="date"></label><label class="full">Catatan<textarea id="puNote"></textarea></label></div><small class="hint">Jika dipilih Hutang, saldo otomatis masuk ke menu Hutang & Piutang.</small>`,async m=>{const pid=m.querySelector('#puProd').value,p=pd.items.find(x=>x.id===pid),qty=Number(m.querySelector('#puQty').value),cost=Number(m.querySelector('#puCost').value||p.cost),total=qty*cost,payStatus=m.querySelector('#puPayStatus').value;await api('/api/purchases-v2',{method:'POST',body:JSON.stringify({supplierId:m.querySelector('#puSup').value,note:m.querySelector('#puNote').value,dueDate:m.querySelector('#puDue').value||null,paidAmount:payStatus==='paid'?total:0,items:[{productId:pid,qty,cost}]})});toast('Pembelian diposting');renderPurchases()})}
async function renderSales(){setActive('sales');const [d,c]=await Promise.all([api('/api/sales'),api('/api/partners?type=customer')]);window._sales=d.items;window._saleCustomers=c.items;$('#content').innerHTML=pageHead('Riwayat Penjualan','Daftar transaksi kasir yang sudah selesai.')+`<div class="card"><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Tanggal</th><th>Kasir</th><th>Pelanggan</th><th>Item</th><th>Metode</th><th class="right">Total</th><th class="action-cell">Aksi</th></tr></thead><tbody>${d.items.map(x=>`<tr><td><b>${x.invoice}</b></td><td>${date(x.createdAt)}</td><td>${x.cashier}</td><td>${c.items.find(y=>y.id===x.customerId)?.name||'Umum'}</td><td>${x.items.reduce((a,b)=>a+b.qty,0)}</td><td>${x.paymentMethod}</td><td class="right"><b>${fmt(x.total)}</b></td><td class="action-cell"><button class="action-btn edit" onclick="editSale('${x.id}')">Edit</button><button class="action-btn edit" onclick="returnSale('${x.id}')">Retur</button><button class="action-btn delete" onclick="voidSale('${x.id}')">Void</button><button class="action-btn delete subtle" onclick="deleteSale('${x.id}')">Hapus</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">Belum ada penjualan.</td></tr>'}</tbody></table></div></div>`}
function editSale(id){const x=window._sales.find(v=>v.id===id);if(!x)return;openModal('Edit Transaksi Penjualan',`<div class="form-grid"><label class="full">Pelanggan<select id="esCust"><option value="">Pelanggan Umum</option>${window._saleCustomers.map(c=>`<option value="${c.id}" ${c.id===x.customerId?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Metode Pembayaran<select id="esPay"><option value="cash" ${x.paymentMethod==='cash'?'selected':''}>Tunai</option><option value="qris" ${x.paymentMethod==='qris'?'selected':''}>QRIS</option><option value="transfer" ${x.paymentMethod==='transfer'?'selected':''}>Transfer</option><option value="card" ${x.paymentMethod==='card'?'selected':''}>Kartu</option><option value="other" ${x.paymentMethod==='other'?'selected':''}>Lainnya</option></select></label><label>Diskon<input id="esDisc" type="number" min="0" value="${Number(x.discount||0)}"></label><label>Uang Dibayar<input id="esPaid" type="number" min="0" value="${Number(x.paid||0)}"></label><label>Total Saat Ini<input value="${fmt(x.total)}" disabled></label></div><small class="hint">Produk dan kuantitas tetap dikunci untuk menjaga histori stok. Jika transaksi salah total, hapus transaksi lalu input ulang dari Kasir.</small>`,async m=>{await api('/api/sales/'+id,{method:'PUT',body:JSON.stringify({customerId:m.querySelector('#esCust').value,paymentMethod:m.querySelector('#esPay').value,discount:Number(m.querySelector('#esDisc').value),paid:Number(m.querySelector('#esPaid').value)})});toast('Penjualan diperbarui');renderSales()})}
async function deleteSale(id){const x=window._sales.find(v=>v.id===id);if(!x||!confirm(`Hapus transaksi ${x.invoice}? Stok barang akan dikembalikan.`))return;try{await api('/api/sales/'+id,{method:'DELETE'});toast('Transaksi penjualan dihapus');renderSales()}catch(e){toast(e.message,true)}}
async function renderPartners(){setActive('partners');const d=await api('/api/partners');window._partners=d.items;const cards=(type)=>d.items.filter(x=>x.type===type).map(x=>`<div class="partner-card" style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;gap:12px"><div><b>${safeHtml(x.name)}</b><small style="display:block;color:var(--muted)">${safeHtml(x.code)} • ${safeHtml(x.phone||'tanpa telepon')}</small></div><div class="action-cell"><button class="action-btn edit" onclick="partnerModal('${x.id}')">Edit</button><button class="action-btn delete" onclick="deletePartner('${x.id}')">Hapus</button></div></div>${type==='customer'?`<div style="margin-top:8px">Poin: <b>${x.points||0}</b></div>`:''}</div>`).join('')||`<div class="empty">Belum ada ${type==='customer'?'pelanggan':'supplier'}.</div>`;$('#content').innerHTML=pageHead('Pelanggan & Supplier','Kelola relasi bisnis dalam satu master data.','<button class="primary" onclick="partnerModal()">+ Tambah Partner</button>')+`<div class="partner-board"><div class="card"><div class="section-title"><h3>Pelanggan</h3><span>${d.items.filter(x=>x.type==='customer').length}</span></div>${cards('customer')}</div><div class="card"><div class="section-title"><h3>Supplier</h3><span>${d.items.filter(x=>x.type==='supplier').length}</span></div>${cards('supplier')}</div></div>`}
function partnerModal(id){const x=id?window._partners.find(v=>v.id===id):{};openModal(id?'Edit Partner':'Tambah Partner',`<div class="form-grid"><label>Tipe<select id="ptType"><option value="customer" ${x.type==='customer'?'selected':''}>Pelanggan</option><option value="supplier" ${x.type==='supplier'?'selected':''}>Supplier</option></select></label><label>Kode<input id="ptCode" value="${x.code||''}"></label><label class="full">Nama<input id="ptName" value="${x.name||''}"></label><label>Telepon<input id="ptPhone" value="${x.phone||''}"></label><label>Email<input id="ptEmail" value="${x.email||''}"></label><label class="full">Alamat<textarea id="ptAddress">${x.address||''}</textarea></label></div>`,async m=>{const b={type:m.querySelector('#ptType').value,code:m.querySelector('#ptCode').value,name:m.querySelector('#ptName').value,phone:m.querySelector('#ptPhone').value,email:m.querySelector('#ptEmail').value,address:m.querySelector('#ptAddress').value};await api(id?'/api/partners/'+id:'/api/partners',{method:id?'PUT':'POST',body:JSON.stringify(b)});toast('Partner disimpan');renderPartners()})}
async function deletePartner(id){const x=window._partners.find(v=>v.id===id);if(!x||!confirm(`Hapus ${x.type==='customer'?'pelanggan':'supplier'} ${x.name}?`))return;await api('/api/partners/'+id,{method:'DELETE'});toast('Partner dihapus');renderPartners()}

async function renderPromotions(){setActive('promotions');const [p,l,txs]=await Promise.all([api('/api/promotions'),api('/api/loyalty/settings'),api('/api/loyalty/transactions')]);window._promotions=p.items;$('#content').innerHTML=pageHead('Promo & Loyalty','Buat voucher, diskon, harga member melalui promo, serta kelola aturan poin pelanggan.','<button class="primary" onclick="promotionModal()">+ Promo Baru</button>')+`<div class="grid-2"><div class="card"><div class="section-title"><h3>Promo & Voucher</h3><small>${p.items.filter(x=>x.active).length} aktif</small></div><div class="table-wrap"><table><thead><tr><th>Promo</th><th>Kode</th><th>Nilai</th><th>Minimum</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${p.items.map(x=>`<tr><td><b>${safeHtml(x.name)}</b>${x.memberOnly?'<small class="member-only">Khusus member</small>':''}</td><td><code>${safeHtml(x.code||'-')}</code></td><td>${x.type==='percent'?num(x.value)+'%':fmt(x.value)}</td><td>${fmt(x.minPurchase)}</td><td><span class="status-chip ${x.active?'ok':'low'}">${x.active?'Aktif':'Nonaktif'}</span></td><td><button class="action-btn edit" onclick="promotionModal('${x.id}')">Edit</button><button class="action-btn delete" onclick="deletePromotion('${x.id}')">Hapus</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Belum ada promo.</td></tr>'}</tbody></table></div></div><div class="card"><h3>Aturan Loyalty</h3><div class="form-grid"><label>Status<select id="loEnabled"><option value="1" ${l.enabled?'selected':''}>Aktif</option><option value="0" ${!l.enabled?'selected':''}>Nonaktif</option></select></label><label>Belanja untuk 1 poin<input id="loEarn" type="number" value="${l.rupiahPerPoint}"></label><label>Nilai 1 poin<input id="loValue" type="number" value="${l.pointValue}"></label><label>Minimum redeem<input id="loMin" type="number" value="${l.minRedeemPoints}"></label></div><button class="primary" onclick="saveLoyalty()">Simpan Aturan</button><div class="loyalty-example">Contoh: belanja ${fmt(l.rupiahPerPoint)} mendapat 1 poin, dan 1 poin bernilai ${fmt(l.pointValue)} saat diredeem.</div></div></div><div class="card" style="margin-top:18px"><div class="section-title"><h3>Aktivitas Poin Terbaru</h3><small>${txs.items.length} catatan</small></div><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Pelanggan</th><th>Invoice</th><th>Tipe</th><th>Poin</th><th>Catatan</th></tr></thead><tbody>${txs.items.slice(0,100).map(x=>`<tr><td>${date(x.at)}</td><td>${safeHtml(x.customer)}</td><td>${safeHtml(x.invoice||'-')}</td><td>${safeHtml(x.type)}</td><td><b>${x.points>0?'+':''}${num(x.points)}</b></td><td>${safeHtml(x.note)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Belum ada aktivitas poin.</td></tr>'}</tbody></table></div></div>`}
function promotionModal(id=''){const x=(window._promotions||[]).find(v=>v.id===id)||{};openModal(id?'Edit Promo':'Promo Baru',`<div class="form-grid"><label>Nama Promo<input id="prName" value="${safeHtml(x.name||'')}"></label><label>Kode Voucher<input id="prCode" value="${safeHtml(x.code||'')}" placeholder="HEMAT10"></label><label>Tipe<select id="prType"><option value="percent" ${x.type==='percent'?'selected':''}>Diskon %</option><option value="fixed" ${x.type==='fixed'?'selected':''}>Diskon Nominal</option></select></label><label>Nilai<input id="prValue" type="number" min="0" value="${x.value||0}"></label><label>Minimum Belanja<input id="prMin" type="number" min="0" value="${x.minPurchase||0}"></label><label>Khusus Member<select id="prMember"><option value="0" ${!x.memberOnly?'selected':''}>Tidak</option><option value="1" ${x.memberOnly?'selected':''}>Ya</option></select></label><label>Mulai<input id="prStart" type="date" value="${x.startsAt?String(x.startsAt).slice(0,10):''}"></label><label>Berakhir<input id="prEnd" type="date" value="${x.endsAt?String(x.endsAt).slice(0,10):''}"></label><label>Status<select id="prActive"><option value="1" ${x.active!==false?'selected':''}>Aktif</option><option value="0" ${x.active===false?'selected':''}>Nonaktif</option></select></label></div>`,async m=>{const body={name:m.querySelector('#prName').value,code:m.querySelector('#prCode').value,type:m.querySelector('#prType').value,value:Number(m.querySelector('#prValue').value),minPurchase:Number(m.querySelector('#prMin').value),memberOnly:m.querySelector('#prMember').value==='1',startsAt:m.querySelector('#prStart').value||null,endsAt:m.querySelector('#prEnd').value||null,active:m.querySelector('#prActive').value==='1'};await api(id?`/api/promotions/${id}`:'/api/promotions',{method:id?'PUT':'POST',body:JSON.stringify(body)});toast('Promo disimpan');renderPromotions()})}
async function deletePromotion(id){if(!confirm('Hapus promo ini?'))return;await api(`/api/promotions/${id}`,{method:'DELETE'});toast('Promo dihapus');renderPromotions()}
async function saveLoyalty(){await api('/api/loyalty/settings',{method:'PUT',body:JSON.stringify({enabled:$('#loEnabled').value==='1',rupiahPerPoint:Number($('#loEarn').value),pointValue:Number($('#loValue').value),minRedeemPoints:Number($('#loMin').value)})});toast('Aturan loyalty disimpan');renderPromotions()}

async function renderReturns(){setActive('returns');const d=await api('/api/returns');$('#content').innerHTML=pageHead('Retur & Void','Penanganan pembatalan transaksi yang aman, mengembalikan stok dan menyimpan alasan untuk audit.',`<button class="secondary" onclick="go('sales')">Pilih dari Riwayat Penjualan</button>`)+`<div class="card"><div class="table-wrap"><table><thead><tr><th>No.</th><th>Tanggal</th><th>Invoice</th><th>Tipe</th><th>Alasan</th><th>Item</th><th>Refund</th><th>User</th></tr></thead><tbody>${d.items.map(x=>`<tr><td><b>${safeHtml(x.number)}</b></td><td>${date(x.created_at)}</td><td>${safeHtml(x.invoice)}</td><td><span class="status-chip ${x.type==='void'?'low':'ok'}">${x.type==='void'?'VOID':'RETUR'}</span></td><td>${safeHtml(x.reason)}</td><td>${x.items.reduce((a,b)=>a+Number(b.qty||0),0)}</td><td>${fmt(x.refund_amount)}</td><td>${safeHtml(x.created_by_name||'-')}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Belum ada retur atau void.</td></tr>'}</tbody></table></div></div>`}
async function returnSale(id){const s=(window._sales||[]).find(x=>x.id===id);if(!s)return;openModal(`Retur ${s.invoice}`,`<p class="hint">Masukkan qty yang dikembalikan. Isi 0 untuk item yang tidak diretur.</p><div class="return-items">${s.items.map((it,i)=>`<label>${safeHtml(it.name)} <small>Terjual ${num(it.qty)}</small><input data-ret-product="${it.productId}" type="number" min="0" max="${it.qty}" value="0"></label>`).join('')}</div><div class="form-grid"><label class="full">Alasan Retur<textarea id="retReason" placeholder="Wajib diisi"></textarea></label><label>Metode Refund<select id="retMethod"><option value="cash">Tunai</option><option value="qris">QRIS</option><option value="transfer">Transfer</option><option value="card">Kartu</option></select></label></div>`,async m=>{const items=[...m.querySelectorAll('[data-ret-product]')].map(x=>({productId:x.dataset.retProduct,qty:Number(x.value||0)})).filter(x=>x.qty>0);await api(`/api/sales/${id}/return`,{method:'POST',body:JSON.stringify({items,reason:m.querySelector('#retReason').value,refundMethod:m.querySelector('#retMethod').value})});toast('Retur berhasil dicatat');renderSales()})}
function voidSale(id){const s=(window._sales||[]).find(x=>x.id===id);if(!s)return;openModal(`Void ${s.invoice}`,`<div class="danger-panel"><b>Void transaksi penuh</b><p>Semua stok akan dikembalikan. Transaksi tetap tersimpan untuk audit dan tidak dihapus dari histori.</p></div><label>Alasan Void<textarea id="voidReason" placeholder="Contoh: salah input transaksi"></textarea></label><label>Metode Refund<select id="voidRefund"><option value="cash">Tunai</option><option value="qris">QRIS</option><option value="transfer">Transfer</option><option value="card">Kartu</option></select></label>`,async m=>{await api(`/api/sales/${id}/void`,{method:'POST',body:JSON.stringify({reason:m.querySelector('#voidReason').value,refundMethod:m.querySelector('#voidRefund').value})});toast('Transaksi berhasil di-void');renderSales()})}

async function renderFinance(){setActive('finance');const [ar,ap]=await Promise.all([api('/api/finance/receivables'),api('/api/finance/payables')]);const arOpen=ar.items.filter(x=>x.status==='open').reduce((a,b)=>a+Number(b.balance||0),0),apOpen=ap.items.filter(x=>x.status==='open').reduce((a,b)=>a+Number(b.balance||0),0);$('#content').innerHTML=pageHead('Hutang & Piutang','Pantau jatuh tempo, saldo, cicilan, dan histori pelunasan customer maupun supplier.')+`<div class="kpis">${kpi('Piutang Berjalan',fmt(arOpen),'↗')}${kpi('Hutang Berjalan',fmt(apOpen),'⇩')}${kpi('Piutang Terbuka',num(ar.items.filter(x=>x.status==='open').length),'#')}${kpi('Hutang Terbuka',num(ap.items.filter(x=>x.status==='open').length),'#')}</div><div class="grid-2"><div class="card"><div class="section-title"><h3>Piutang Pelanggan</h3></div><div class="table-wrap"><table><thead><tr><th>Pelanggan</th><th>Referensi</th><th>Jatuh Tempo</th><th>Saldo</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${ar.items.map(x=>`<tr><td><b>${safeHtml(x.partner)}</b></td><td>${safeHtml(x.invoice||x.number)}</td><td>${x.due_date?String(x.due_date).slice(0,10):'-'}</td><td>${fmt(x.balance)}</td><td><span class="status-chip ${x.status==='paid'?'ok':'low'}">${x.status}</span></td><td>${x.status==='open'?`<button class="action-btn edit" onclick="payFinance('receivables','${x.id}',${Number(x.balance)})">Terima</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Tidak ada piutang.</td></tr>'}</tbody></table></div></div><div class="card"><div class="section-title"><h3>Hutang Supplier</h3></div><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Referensi</th><th>Jatuh Tempo</th><th>Saldo</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${ap.items.map(x=>`<tr><td><b>${safeHtml(x.partner)}</b></td><td>${safeHtml(x.purchase_number||x.number)}</td><td>${x.due_date?String(x.due_date).slice(0,10):'-'}</td><td>${fmt(x.balance)}</td><td><span class="status-chip ${x.status==='paid'?'ok':'low'}">${x.status}</span></td><td>${x.status==='open'?`<button class="action-btn edit" onclick="payFinance('payables','${x.id}',${Number(x.balance)})">Bayar</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Tidak ada hutang.</td></tr>'}</tbody></table></div></div></div>`}
function payFinance(kind,id,balance){openModal(kind==='receivables'?'Terima Pembayaran Piutang':'Bayar Hutang',`<div class="form-grid"><label>Sisa Saldo<input value="${fmt(balance)}" disabled></label><label>Jumlah<input id="finAmount" type="number" min="1" max="${balance}" value="${balance}"></label><label>Metode<select id="finMethod"><option value="cash">Tunai</option><option value="qris">QRIS</option><option value="transfer">Transfer</option><option value="card">Kartu</option></select></label><label>Referensi<input id="finRef" placeholder="No. transfer / catatan"></label></div>`,async m=>{await api(`/api/finance/${kind}/${id}/pay`,{method:'POST',body:JSON.stringify({amount:Number(m.querySelector('#finAmount').value),method:m.querySelector('#finMethod').value,reference:m.querySelector('#finRef').value})});toast('Pembayaran dicatat');renderFinance()})}

async function renderDevices(){setActive('devices');const [d,p]=await Promise.all([api('/api/device-settings'),api('/api/products')]);window._deviceProducts=p.items;$('#content').innerHTML=pageHead('Printer & Barcode','Siapkan struk thermal, scan barcode kamera, label produk, dan mode aplikasi offline/PWA.')+`<div class="grid-2"><div class="card"><h3>Printer Struk</h3><div class="form-grid"><label>Lebar Kertas<select id="dvPaper"><option value="58" ${d.receiptPaperWidth===58?'selected':''}>58 mm</option><option value="80" ${d.receiptPaperWidth!==58?'selected':''}>80 mm</option></select></label><label>Cetak Otomatis<select id="dvAuto"><option value="1" ${d.receiptAutoPrint?'selected':''}>Ya</option><option value="0" ${!d.receiptAutoPrint?'selected':''}>Tidak</option></select></label></div><div class="device-actions"><button class="primary" onclick="saveDeviceSettings()">Simpan</button><button class="secondary" onclick="testPrint()">Test Print</button></div><p class="hint">Printer USB/LAN/Bluetooth yang sudah dikenali sistem dapat dipilih dari dialog cetak browser. Untuk kiosk khusus, gunakan driver/print bridge perangkat.</p></div><div class="card"><h3>Barcode Scanner</h3><p class="hint">Scanner USB bekerja seperti keyboard. Untuk perangkat dengan kamera dan browser yang mendukung BarcodeDetector, gunakan scanner kamera.</p><button class="primary" onclick="startBarcodeScan(true)">Buka Scanner Kamera</button><div class="barcode-test"><input id="barcodeTest" placeholder="Scan barcode di sini"><button class="secondary" onclick="findBarcodeProduct()">Cari Produk</button></div></div></div><div class="card" style="margin-top:18px"><div class="section-title"><h3>Cetak Label Barcode Produk</h3><button class="secondary" onclick="printSelectedBarcodes()">Cetak Label Terpilih</button></div><div class="barcode-product-grid">${p.items.filter(x=>x.active!==false).map(x=>`<label class="barcode-product"><input type="checkbox" data-label-product="${x.id}"><span><b>${safeHtml(x.name)}</b><small>${safeHtml(x.barcode||x.sku)}</small></span></label>`).join('')}</div></div><div class="card pwa-card" style="margin-top:18px"><h3>Mode Offline / PWA</h3><p>ACIS POS menyimpan file aplikasi agar tetap dapat dibuka saat koneksi terputus. Checkout yang gagal karena internet putus akan masuk antrean lokal dan disinkronkan kembali saat online.</p><div><span class="status-chip ${navigator.onLine?'ok':'low'}">${navigator.onLine?'Online':'Offline'}</span> <span>${pendingSales().length} transaksi pending</span></div><button class="primary" onclick="syncPendingSales()">Sinkronkan Sekarang</button></div>`}
async function saveDeviceSettings(){await api('/api/device-settings',{method:'PUT',body:JSON.stringify({receiptPaperWidth:Number($('#dvPaper').value),receiptAutoPrint:$('#dvAuto').value==='1',barcodeLabelWidth:50})});toast('Pengaturan perangkat disimpan')}
function testPrint(){const w=window.open('','_blank','width=360,height=500');w.document.write(`<html><body style="font:14px monospace;text-align:center;padding:20px"><img src="/assets/acis-pos-logo.png" style="width:150px"><h3>TEST PRINT ACIS POS</h3><p>${new Date().toLocaleString('id-ID')}</p><hr><p>Printer siap digunakan.</p><script>print()<\/script></body></html>`);w.document.close()}
function findBarcodeProduct(){const q=$('#barcodeTest').value.trim(),p=(window._deviceProducts||[]).find(x=>x.barcode===q||x.sku===q);toast(p?`${p.name} — ${fmt(p.price)}`:'Produk tidak ditemukan',!p)}
function printSelectedBarcodes(){const ids=[...document.querySelectorAll('[data-label-product]:checked')].map(x=>x.dataset.labelProduct),items=(window._deviceProducts||[]).filter(x=>ids.includes(x.id));if(!items.length)return toast('Pilih minimal satu produk.',true);const w=window.open('','_blank');w.document.write(`<html><head><style>@page{margin:5mm}body{font-family:Arial;display:flex;flex-wrap:wrap;gap:8px}.label{width:50mm;border:1px solid #ddd;padding:7px;text-align:center;page-break-inside:avoid}.bars{font-family:monospace;letter-spacing:2px;font-size:22px;overflow:hidden}.code{font:12px monospace}</style></head><body>${items.map(x=>`<div class="label"><b>${safeHtml(x.name)}</b><div class="bars">||| || ||| | |||| || |</div><div class="code">${safeHtml(x.barcode||x.sku)}</div><strong>${fmt(x.price)}</strong></div>`).join('')}<script>print()<\/script></body></html>`);w.document.close()}
async function startBarcodeScan(deviceOnly=false){if(!('BarcodeDetector' in window))return toast('Scanner kamera belum didukung browser ini. Gunakan scanner USB atau masukkan barcode manual.',true);const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-card scan-card"><div class="modal-head"><h3>Scan Barcode Kamera</h3><button class="close">×</button></div><video id="scanVideo" autoplay playsinline></video><p class="hint">Arahkan kamera ke barcode produk.</p></div>`;document.body.appendChild(m);const video=m.querySelector('video');let stream;let timer;const close=()=>{clearInterval(timer);stream?.getTracks().forEach(t=>t.stop());m.remove()};m.querySelector('.close').onclick=close;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=stream;const detector=new BarcodeDetector({formats:['code_128','ean_13','ean_8','upc_a','upc_e','qr_code']});timer=setInterval(async()=>{try{const codes=await detector.detect(video);if(!codes.length)return;const value=codes[0].rawValue;close();if(deviceOnly){const p=(window._deviceProducts||[]).find(x=>x.barcode===value||x.sku===value);toast(p?`${p.name} — ${fmt(p.price)}`:`Barcode ${value} belum terdaftar`,!p)}else{const p=(window._posProducts||[]).find(x=>x.barcode===value||x.sku===value);if(p){addCart(p.id);toast(`${p.name} ditambahkan`)}else toast(`Barcode ${value} belum terdaftar`,true)}}catch{}},450)}catch(e){close();toast('Kamera tidak dapat diakses.',true)}}

async function renderReports(){setActive('reports');const to=new Date().toISOString().slice(0,10),from=to.slice(0,8)+'01';const reports=[['sales_item','Penjualan per Barang'],['sales_payment','Penjualan per Metode Bayar'],['sales_shift','Penjualan per Shift'],['sales_customer','Penjualan per Pelanggan'],['purchase_item','Pembelian per Barang'],['purchase_supplier','Pembelian per Pemasok'],['ap','Hutang Usaha'],['ar','Piutang Usaha'],['receipts_payment','Penerimaan Uang per Metode Bayar'],['ledger','Buku Besar'],['profit_loss','Laba Rugi'],['balance_sheet','Neraca / Posisi Keuangan']];$('#content').innerHTML=pageHead('Laporan','Laporan operasional dan keuangan yang siap ditinjau atau diekspor.')+`<div class="report-picker card"><div class="toolbar"><label>Dari<input id="rFrom" type="date" value="${from}"></label><label>Sampai<input id="rTo" type="date" value="${to}"></label></div><div class="report-menu">${reports.map((r,i)=>`<button class="${i===0?'active':''}" onclick="loadReport('${r[0]}',this)">${r[1]}</button>`).join('')}</div></div><div id="reportResult" class="card" style="margin-top:18px"></div>`;loadReport('sales_item')}
async function exportReport(type,format){const from=$('#rFrom').value,to=$('#rTo').value;const r=await fetch(`/api/reports/export?type=${encodeURIComponent(type)}&format=${format}&from=${from}&to=${to}`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok){let e={};try{e=await r.json()}catch{}return toast(e.error||'Ekspor gagal',true)}const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);const cd=r.headers.get('content-disposition')||'',m=cd.match(/filename="?([^";]+)"?/);a.download=m?.[1]||`laporan.${format==='pdf'?'pdf':'xlsx'}`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function loadReport(type,btn){window._currentReport=type;document.querySelectorAll('.report-menu button').forEach(x=>x.classList.remove('active'));btn?.classList.add('active');const from=$('#rFrom').value,to=$('#rTo').value,d=await api(`/api/reports/detail?type=${encodeURIComponent(type)}&from=${from}&to=${to}`);const rows=d.rows||[];const moneyKeys=['total','omzet','saldo','penerimaan','nilai','nilai_penjualan','debit','kredit','dibayar','amount'];const actions=`<div class="report-actions"><button class="secondary" onclick="exportReport('${type}','xlsx')">Ekspor Excel</button><button class="secondary" onclick="exportReport('${type}','pdf')">Ekspor PDF</button><button class="ghost" onclick="loadReport('${type}')">Refresh</button></div>`;if(['profit_loss','balance_sheet'].includes(type)){const groups={};rows.forEach(r=>(groups[r.section]??=[]).push(r));$('#reportResult').innerHTML=`<div class="section-title"><div><h3>${d.title}</h3><small>${type==='balance_sheet'?'Per '+to:from+' s/d '+to}</small></div>${actions}</div>${d.note?`<div class="report-note">${safeHtml(d.note)}</div>`:''}<div class="financial-statement">${Object.entries(groups).map(([g,rs])=>`<div class="financial-section"><h4>${safeHtml(g)}</h4>${rs.map(r=>`<div class="financial-row ${r.total?'total':''}"><span>${safeHtml(r.account)}</span><b>${fmt(r.amount)}</b></div>`).join('')}</div>`).join('')}</div>`;return}const keys=rows[0]?Object.keys(rows[0]):[];const cell=(k,v)=>moneyKeys.includes(k)?fmt(v):(k==='tanggal'||k==='mulai'||k==='selesai'?safeHtml(v?date(v):'-'):safeHtml(v??'-'));$('#reportResult').innerHTML=`<div class="section-title"><div><h3>${d.title}</h3><small>${from} s/d ${to}</small></div>${actions}</div>${d.note?`<div class="report-note">${safeHtml(d.note)}</div>`:''}<div class="table-wrap"><table><thead><tr>${keys.map(k=>`<th>${k.replaceAll('_',' ')}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${cell(k,r[k])}</td>`).join('')}</tr>`).join('')||`<tr><td class="empty" colspan="${Math.max(keys.length,1)}">Belum ada data pada periode ini.</td></tr>`}</tbody></table></div>`}

async function renderExpenses(){setActive('expenses');const d=await api('/api/expenses');window._expenses=d.items;$('#content').innerHTML=pageHead('Biaya Operasional','Catat pengeluaran untuk perhitungan laba bersih.','<button class="primary" onclick="expenseModal()">+ Tambah Biaya</button>')+`<div class="card"><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Kategori</th><th>Deskripsi</th><th class="right">Jumlah</th><th class="action-cell">Aksi</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${date(x.createdAt)}</td><td>${x.category}</td><td>${x.description}</td><td class="right"><b>${fmt(x.amount)}</b></td><td class="action-cell"><button class="action-btn edit" onclick="editExpense('${x.id}')">Edit</button><button class="action-btn delete" onclick="deleteExpense('${x.id}')">Hapus</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Belum ada biaya.</td></tr>'}</tbody></table></div></div>`}
function editExpense(id){const x=window._expenses.find(v=>v.id===id);if(!x)return;openModal('Edit Biaya',`<div class="form-grid"><label>Kategori<input id="eeCat" value="${x.category||''}"></label><label>Jumlah<input id="eeAmount" type="number" min="0" value="${Number(x.amount||0)}"></label><label class="full">Deskripsi<input id="eeDesc" value="${x.description||''}"></label></div>`,async m=>{await api('/api/expenses/'+id,{method:'PUT',body:JSON.stringify({category:m.querySelector('#eeCat').value,amount:Number(m.querySelector('#eeAmount').value),description:m.querySelector('#eeDesc').value})});toast('Biaya diperbarui');renderExpenses()})}
async function deleteExpense(id){const x=window._expenses.find(v=>v.id===id);if(!x||!confirm(`Hapus biaya ${x.description||x.category}?`))return;try{await api('/api/expenses/'+id,{method:'DELETE'});toast('Biaya dihapus');renderExpenses()}catch(e){toast(e.message,true)}}
function expenseModal(){openModal('Tambah Biaya',`<div class="form-grid"><label>Kategori<input id="eCat" value="Operasional"></label><label>Jumlah<input id="eAmount" type="number" min="0"></label><label class="full">Deskripsi<input id="eDesc"></label></div>`,async m=>{await api('/api/expenses',{method:'POST',body:JSON.stringify({category:m.querySelector('#eCat').value,amount:Number(m.querySelector('#eAmount').value),description:m.querySelector('#eDesc').value})});toast('Biaya dicatat');renderExpenses()})}
async function renderUsers(){setActive('users');const d=await api('/api/users');$('#content').innerHTML=pageHead('User & Role','Kelola akun operator dan hak akses dasar.','<button class="primary" onclick="userModal()">+ Tambah User</button>')+`<div class="card"><table><thead><tr><th>Nama</th><th>Username</th><th>Role</th><th>Status</th><th>Dibuat</th></tr></thead><tbody>${d.items.map(x=>`<tr><td><b>${x.name}</b></td><td>${x.username}</td><td>${x.role}</td><td><span class="status-chip ${x.active?'stock-chip ok':'stock-chip low'}">${x.active?'Aktif':'Nonaktif'}</span></td><td>${date(x.createdAt)}</td></tr>`).join('')}</tbody></table></div>`}
function userModal(){openModal('Tambah User',`<div class="form-grid"><label>Nama<input id="uName"></label><label>Username<input id="uUsername"></label><label>Password<input id="uPassword" type="password" value="123456"></label><label>Role<select id="uRole">${master.roles.map(x=>`<option>${x.name}</option>`).join('')}</select></label></div>`,async m=>{await api('/api/users',{method:'POST',body:JSON.stringify({name:m.querySelector('#uName').value,username:m.querySelector('#uUsername').value,password:m.querySelector('#uPassword').value,role:m.querySelector('#uRole').value})});toast('User dibuat');renderUsers()})}
async function renderSettings(tab='profile'){setActive('settings');const s=await api('/api/settings');const menu=`<div class="settings-menu"><button class="${tab==='profile'?'active':''}" onclick="renderSettings('profile')">Profil Usaha</button><button class="${tab==='receipt'?'active':''}" onclick="renderSettings('receipt')">Struk</button><button class="${tab==='stock'?'active':''}" onclick="renderSettings('stock')">Stok</button><button class="${tab==='security'?'active':''}" onclick="renderSettings('security')">Keamanan</button></div>`;let body='';if(tab==='profile')body=`<div class="card"><div class="section-title"><h3>Profil Usaha</h3><img src="/assets/acis-pos-logo.png" alt="ACIS POS" style="width:190px;max-width:42vw;height:auto;object-fit:contain"></div><div class="form-grid"><label class="full">Nama Usaha<input id="sName" value="${s.companyName||''}"></label><label>Telepon<input id="sPhone" value="${s.phone||''}"></label><label>Email<input id="sEmail" value="${s.email||''}"></label><label class="full">Alamat<textarea id="sAddress">${s.address||''}</textarea></label><label>Pajak (%)<input id="sTax" type="number" value="${s.taxRate||0}"></label></div><div style="margin-top:18px"><button class="primary" onclick="saveSettings('profile')">Simpan Perubahan</button></div></div>`;else if(tab==='receipt')body=`<div class="card"><div class="section-title"><h3>Pengaturan Struk</h3><span>Preview langsung</span></div><div class="grid-2"><div class="form-grid"><label class="full">Header Struk<textarea id="sHeader">${s.receiptHeader||''}</textarea></label><label>Lebar Kertas<select id="sPaper"><option value="58" ${s.receiptPaperWidth===58?'selected':''}>58 mm</option><option value="80" ${s.receiptPaperWidth!==58?'selected':''}>80 mm</option></select></label><label>Tampilkan Logo<select id="sLogo"><option value="1" ${s.receiptShowLogo?'selected':''}>Ya</option><option value="0" ${!s.receiptShowLogo?'selected':''}>Tidak</option></select></label><label class="full">Footer Struk<textarea id="sFooter">${s.receiptFooter||''}</textarea></label><div class="full"><button class="primary" onclick="saveSettings('receipt')">Simpan Pengaturan Struk</button></div></div><div class="receipt-preview">${s.receiptShowLogo?'<img src="/assets/acis-pos-logo.png">':''}<h4>${safeHtml(s.companyName)}</h4><small>${safeHtml(s.address||'Alamat toko')}</small><div class="receipt-dash"></div><p>${safeHtml(s.receiptHeader||'Struk Penjualan')}</p><div class="receipt-line"><span>Contoh Produk</span><b>Rp 25.000</b></div><div class="receipt-dash"></div><div class="receipt-line"><b>TOTAL</b><b>Rp 25.000</b></div><p>${safeHtml(s.receiptFooter||'Terima kasih')}</p></div></div></div>`;else if(tab==='stock')body=`<div class="card"><h3>Pengaturan Stok</h3><div class="form-grid"><label>Stok Minimum Default<input id="sLow" type="number" value="${s.lowStockThreshold||5}"></label></div><div style="margin-top:18px"><button class="primary" onclick="saveSettings('stock')">Simpan Pengaturan Stok</button></div></div>`;else body=`<div class="card"><h3>Keamanan</h3><p style="color:var(--muted);line-height:1.7">Sesi login menggunakan JWT dan seluruh data bisnis terisolasi berdasarkan tenant. Gunakan password kuat dan batasi hak akses user melalui menu User & Role.</p><div class="saas-tags"><span>Multi-tenant</span><span>Role based access</span><span>Audit log</span></div></div>`;$('#content').innerHTML=pageHead('Pengaturan','Identitas usaha, struk, stok, dan keamanan operasional.')+`<div class="settings-shell">${menu}${body}</div>`}
async function saveSettings(tab='profile'){const b={};if(tab==='profile'){b.companyName=$('#sName').value;b.phone=$('#sPhone').value;b.email=$('#sEmail').value;b.address=$('#sAddress').value;b.taxRate=Number($('#sTax').value||0)}if(tab==='receipt'){b.receiptHeader=$('#sHeader').value;b.receiptFooter=$('#sFooter').value;b.receiptPaperWidth=Number($('#sPaper').value||80);b.receiptShowLogo=$('#sLogo').value==='1'}if(tab==='stock')b.lowStockThreshold=Number($('#sLow').value||5);await api('/api/settings',{method:'PUT',body:JSON.stringify(b)});toast('Pengaturan disimpan');renderSettings(tab)}
async function renderIntegration(){setActive('integration');const d=await api('/api/integrations/accurate');let dbBlock='';if(d.status==='authorized'){const db=await api('/api/integrations/accurate/databases');dbBlock=`<div class="card" style="margin-top:16px"><h3>Pilih Data Usaha Accurate</h3><p class="hint">Pilih perusahaan Accurate Online yang akan menerima data ACIS POS.</p><div class="db-grid">${db.items.map(x=>`<button class="db-choice" onclick="selectAccurateDb('${x.id}','${safeHtml(x.alias).replaceAll("'","\\'")}')"><b>${safeHtml(x.alias)}</b><small>${x.expired?'Masa akses berakhir':'Aktif'}</small></button>`).join('')}</div></div>`}const connected=d.connected;$('#content').innerHTML=pageHead('Accurate Online','Kirim Faktur Penjualan dan Penerimaan Penjualan ACIS POS ke Accurate Online.')+`<div class="grid-2"><div class="card integration-simple"><div class="section-title"><h3>${connected?'Accurate Online Terhubung':'Hubungkan Accurate Online'}</h3><span class="status-chip ${connected?'ok':'low'}">${connected?'Terhubung':'Belum terhubung'}</span></div>${connected?`<div class="accurate-connected"><div class="connect-logo">A</div><div><b>${safeHtml(d.databaseAlias||'Data Usaha Accurate')}</b><p>Transaksi hanya dikirim satu arah dari ACIS POS ke Accurate Online.</p></div></div><button class="primary big-action" onclick="syncAccurateNow()">Kirim Data Sekarang</button><button class="ghost" onclick="disconnectAccurate()">Putuskan Hubungan</button>`:`<p class="hint">Klik tombol berikut, login menggunakan akun Accurate Online Anda, kemudian beri izin akses kepada ACIS POS.</p><button class="primary big-action" ${d.oauthReady?'':'disabled'} onclick="connectAccurate()">Hubungkan ke Accurate Online</button>${d.oauthReady?'':'<div class="report-note">Integrasi belum diaktifkan oleh tim ACIS.</div>'}`}</div><div class="card"><h3>Data yang Dikirim</h3><div class="integration-steps"><div><b>1</b><span>Faktur Penjualan dari transaksi POS yang belum pernah dikirim.</span></div><div><b>2</b><span>Penerimaan Penjualan untuk transaksi yang sudah menerima pembayaran.</span></div><div><b>3</b><span>Transaksi yang berhasil dikirim ditandai agar tidak dikirim dua kali.</span></div></div><small style="color:var(--muted)">Terakhir kirim: ${d.lastSyncAt?date(d.lastSyncAt):'Belum pernah'}</small></div></div>${dbBlock}<div id="accurateLogs" style="margin-top:16px"></div>`;loadAccurateLogs()}
async function connectAccurate(){const d=await api('/api/integrations/accurate/oauth/start');const w=window.open(d.url,'accurateOAuth','width=720,height=760');const timer=setInterval(async()=>{if(w?.closed){clearInterval(timer);renderIntegration()}},800)}
async function selectAccurateDb(id,alias){await api('/api/integrations/accurate/select-database',{method:'POST',body:JSON.stringify({databaseId:id,databaseAlias:alias})});toast('Accurate Online terhubung');renderIntegration()}
async function syncAccurateNow(){if(!confirm('Kirim transaksi penjualan yang belum tersinkron ke Accurate Online sekarang?'))return;toast('Mengirim data ke Accurate Online...');try{const d=await api('/api/integrations/accurate/sync-now',{method:'POST',body:'{}'});toast(`${d.sent} transaksi berhasil dikirim${d.failed?`, ${d.failed} gagal`:''}`,!!d.failed);renderIntegration()}catch(e){toast(e.message,true)}}
async function disconnectAccurate(){if(!confirm('Putuskan integrasi Accurate Online?'))return;await api('/api/integrations/accurate/disconnect',{method:'POST',body:'{}'});toast('Integrasi diputus');renderIntegration()}
async function loadAccurateLogs(){const el=$('#accurateLogs');if(!el)return;const d=await api('/api/integrations/accurate/logs');if(!d.items.length)return;el.innerHTML=`<div class="card"><div class="section-title"><h3>Riwayat Pengiriman</h3></div><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Referensi</th><th>Status</th><th>Keterangan</th></tr></thead><tbody>${d.items.slice(0,20).map(x=>`<tr><td>${date(x.created_at)}</td><td>${safeHtml(x.local_reference)}</td><td><span class="status-chip ${x.status==='success'?'ok':'low'}">${x.status}</span></td><td>${safeHtml(x.message)}</td></tr>`).join('')}</tbody></table></div></div>`}

async function renderAudit(){setActive('audit');const d=await api('/api/audit');$('#content').innerHTML=pageHead('Audit Log','Riwayat aktivitas penting untuk penelusuran operasional.')+`<div class="card"><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>User</th><th>Aksi</th><th>Entitas</th><th>Detail</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${date(x.at)}</td><td>${x.user}</td><td><b>${x.action}</b></td><td>${x.entity}</td><td>${x.detail}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Belum ada log.</td></tr>'}</tbody></table></div></div>`}

async function renderSubscription(){setActive('subscription');const s=await api('/api/subscription');const exp=s.expires_at?new Date(s.expires_at).toLocaleDateString('id-ID'):'-';const active=(s.status==='active'||s.status==='trial')&&(!s.expires_at||new Date(s.expires_at)>=new Date());$('#content').innerHTML=pageHead('Langganan','Informasi paket dan masa aktif ACIS POS Anda.')+`<div class="subscription-grid"><div class="card"><div class="section-title"><h3>Paket Saat Ini</h3><span class="status-chip ${active?'ok':'low'}">${active?'Aktif':'Tidak Aktif'}</span></div><div class="subscription-price">${safeHtml(s.plan_name||'Paket ACIS POS')}</div><div class="plan-value">${s.plan_code==='ANNUAL'?fmt(1000000)+' / tahun':fmt(100000)+' / bulan'}</div><div class="subscription-info"><div><span>Berlaku sampai</span><b>${exp}</b></div></div><p class="hint">Perpanjangan dan perubahan periode langganan dikelola oleh tim ACIS.</p></div><div class="card"><h3>Pilihan Paket</h3><div class="package-card"><b>Paket Bulanan</b><strong>${fmt(100000)} / bulan</strong></div><div class="package-card featured"><b>Paket Tahunan</b><strong>${fmt(1000000)} / tahun</strong><small>Hemat dibanding pembayaran bulanan selama 12 bulan.</small></div></div></div>`}

async function renderShifts(){setActive('shifts');const [cur,hist]=await Promise.all([api('/api/shifts/current'),api('/api/shifts')]);const c=cur.shift;$('#content').innerHTML=pageHead('Shift Kasir','Buka dan tutup shift untuk rekonsiliasi kas dan penjualan per kasir.',c?`<button class="primary" onclick="closeShift('${c.id}')">Tutup Shift</button>`:`<button class="primary" onclick="openShift()">Buka Shift</button>`)+`${c?`<div class="kpis">${kpi('Modal Awal',fmt(c.opening_cash),'◉')}${kpi('Transaksi',num(c.transactions),'#')}${kpi('Total Penjualan',fmt(c.sales_total),'↗')}${kpi('Penjualan Tunai',fmt(c.cash_sales),'Rp')}</div>`:`<div class="card empty-state"><h3>Belum ada shift aktif</h3><p>Buka shift sebelum memulai operasional kasir agar laporan per shift lebih akurat.</p></div>`}<div class="card" style="margin-top:18px"><div class="section-title"><h3>Riwayat Shift</h3><small>${hist.items.length} shift</small></div><div class="table-wrap"><table><thead><tr><th>Kasir</th><th>Mulai</th><th>Selesai</th><th>Modal Awal</th><th>Penjualan</th><th>Tunai</th><th>Kas Akhir</th><th>Status</th></tr></thead><tbody>${hist.items.map(x=>`<tr><td><b>${safeHtml(x.cashier)}</b></td><td>${date(x.opened_at)}</td><td>${x.closed_at?date(x.closed_at):'-'}</td><td>${fmt(x.opening_cash)}</td><td>${fmt(x.sales_total)}</td><td>${fmt(x.cash_sales)}</td><td>${x.closing_cash==null?'-':fmt(x.closing_cash)}</td><td><span class="status-chip ${x.status==='open'?'ok':''}">${x.status==='open'?'Aktif':'Ditutup'}</span></td></tr>`).join('')||'<tr><td colspan="8" class="empty">Belum ada riwayat shift.</td></tr>'}</tbody></table></div></div>`}
function openShift(){openModal('Buka Shift',`<div class="form-grid"><label>Modal Kas Awal<input id="shiftOpenCash" type="number" min="0" value="0"></label><label class="full">Catatan<textarea id="shiftNote" placeholder="Opsional"></textarea></label></div>`,async m=>{await api('/api/shifts/open',{method:'POST',body:JSON.stringify({openingCash:Number(m.querySelector('#shiftOpenCash').value||0),notes:m.querySelector('#shiftNote').value})});toast('Shift dibuka');renderShifts()})}
function closeShift(id){openModal('Tutup Shift',`<div class="form-grid"><label>Kas Fisik Akhir<input id="shiftCloseCash" type="number" min="0" value="0"></label><label class="full">Catatan Penutupan<textarea id="shiftCloseNote" placeholder="Opsional"></textarea></label></div>`,async m=>{await api(`/api/shifts/${id}/close`,{method:'POST',body:JSON.stringify({closingCash:Number(m.querySelector('#shiftCloseCash').value||0),notes:m.querySelector('#shiftCloseNote').value})});toast('Shift ditutup');renderShifts()})}

if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/service-worker.js').catch(()=>{}));
window.addEventListener('online',()=>{updateOnlineState();syncPendingSales().catch(()=>{})});
window.addEventListener('offline',updateOnlineState);
if(token)initApp();
